-- Durable coordinator, approvals, fenced actions and independent obligations.
-- 持久协调任务、审批、带栅栏动作及独立履约义务。
CREATE TABLE agent_definition(enterprise_id uuid NOT NULL REFERENCES enterprise(id),id text NOT NULL,version integer NOT NULL,definition jsonb NOT NULL,PRIMARY KEY(enterprise_id,id,version));
CREATE TABLE agent_run(enterprise_id uuid NOT NULL,id uuid NOT NULL,case_id text NOT NULL,agent_id text NOT NULL,agent_version integer NOT NULL,principal_id uuid NOT NULL REFERENCES principal(id),authorization_version integer NOT NULL,policy_version text NOT NULL,state text NOT NULL CHECK(state IN ('ready','running','waiting_approval','waiting_external','waiting_input','paused','succeeded','partially_succeeded','failed','cancelled')),version integer NOT NULL DEFAULT 1,goal jsonb NOT NULL,phase text NOT NULL DEFAULT 'analyze',model_profile text NOT NULL,model_calls integer NOT NULL DEFAULT 0,steps integer NOT NULL DEFAULT 0,model_reserved integer NOT NULL DEFAULT 0,model_used integer NOT NULL DEFAULT 0,model_usage_unknown boolean NOT NULL DEFAULT false,deadline timestamptz NOT NULL,next_wake_at timestamptz,lease_owner text,lease_until timestamptz,fence bigint NOT NULL DEFAULT 0,reason text,summary jsonb,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(enterprise_id,id),FOREIGN KEY(enterprise_id,case_id) REFERENCES case_file(enterprise_id,id),FOREIGN KEY(enterprise_id,agent_id,agent_version) REFERENCES agent_definition(enterprise_id,id,version));
CREATE INDEX runtime_due ON agent_run(state,next_wake_at,lease_until);
CREATE TABLE runtime_task(enterprise_id uuid NOT NULL,id uuid NOT NULL,run_id uuid NOT NULL,parent_id uuid,dependencies uuid[] NOT NULL DEFAULT '{}',state text NOT NULL,version integer NOT NULL DEFAULT 1,lease_owner text,lease_until timestamptz,fence bigint NOT NULL DEFAULT 0,PRIMARY KEY(enterprise_id,id),FOREIGN KEY(enterprise_id,run_id) REFERENCES agent_run(enterprise_id,id));
CREATE TABLE runtime_plan(enterprise_id uuid NOT NULL,id uuid NOT NULL,version integer NOT NULL,run_id uuid NOT NULL,content jsonb NOT NULL,args_hash text NOT NULL,evidence_hash text NOT NULL,constraint_hash text NOT NULL,policy_version text NOT NULL,expires_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN ('proposed','approved','rejected','stale')),PRIMARY KEY(enterprise_id,id,version),FOREIGN KEY(enterprise_id,run_id) REFERENCES agent_run(enterprise_id,id));
CREATE TABLE runtime_approval(enterprise_id uuid NOT NULL,id uuid NOT NULL,plan_id uuid NOT NULL,plan_version integer NOT NULL,approver_id uuid NOT NULL REFERENCES principal(id),decision text NOT NULL CHECK(decision IN ('approve','reject')),binding_hash text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(enterprise_id,id),UNIQUE(enterprise_id,plan_id,plan_version,approver_id),FOREIGN KEY(enterprise_id,plan_id,plan_version) REFERENCES runtime_plan(enterprise_id,id,version));
CREATE TABLE runtime_action(enterprise_id uuid NOT NULL,id uuid NOT NULL,run_id uuid NOT NULL,plan_id uuid NOT NULL,plan_version integer NOT NULL,connector_id text NOT NULL,action_kind text NOT NULL,tool_version text NOT NULL,idempotency_key text NOT NULL,args jsonb NOT NULL,args_hash text NOT NULL,expected_source_version integer NOT NULL,state text NOT NULL CHECK(state IN ('ready','dispatching','submitted','verifying','succeeded','rejected','failed','unknown','cancelled')),commit_state text NOT NULL CHECK(commit_state IN ('not_sent','unknown','committed','not_committed')),fence bigint NOT NULL DEFAULT 0,attempts integer NOT NULL DEFAULT 0,external_ref text,source_version integer,PRIMARY KEY(enterprise_id,id),UNIQUE(enterprise_id,connector_id,action_kind,idempotency_key),FOREIGN KEY(enterprise_id,run_id) REFERENCES agent_run(enterprise_id,id),FOREIGN KEY(enterprise_id,plan_id,plan_version) REFERENCES runtime_plan(enterprise_id,id,version));
CREATE TABLE runtime_receipt(enterprise_id uuid NOT NULL,id text NOT NULL,action_id uuid NOT NULL,external_ref text NOT NULL,source_version integer NOT NULL,state text NOT NULL,payload_hash text NOT NULL,payload jsonb NOT NULL,verified_at timestamptz NOT NULL,PRIMARY KEY(enterprise_id,id),FOREIGN KEY(enterprise_id,action_id) REFERENCES runtime_action(enterprise_id,id));
CREATE TABLE fulfillment_obligation(enterprise_id uuid NOT NULL,id uuid NOT NULL,case_id text NOT NULL,run_id uuid NOT NULL,action_id uuid NOT NULL,kind text NOT NULL,owner_role text NOT NULL,state text NOT NULL CHECK(state IN ('open','manual','closed')),next_check_at timestamptz NOT NULL,deadline timestamptz NOT NULL,evidence_refs jsonb NOT NULL DEFAULT '[]',reason text,PRIMARY KEY(enterprise_id,id),UNIQUE(enterprise_id,action_id),FOREIGN KEY(enterprise_id,action_id) REFERENCES runtime_action(enterprise_id,id));
CREATE INDEX obligations_due ON fulfillment_obligation(state,next_check_at);
ALTER TABLE fulfillment_obligation ADD verification_attempts integer NOT NULL DEFAULT 0;
CREATE TABLE resource_budget(enterprise_id uuid NOT NULL,resource_key text NOT NULL,unit text NOT NULL,limit_qty bigint NOT NULL CHECK(limit_qty>=0),reserved bigint NOT NULL DEFAULT 0 CHECK(reserved>=0),settled bigint NOT NULL DEFAULT 0 CHECK(settled>=0),version integer NOT NULL DEFAULT 1,PRIMARY KEY(enterprise_id,resource_key),CHECK(reserved+settled<=limit_qty));
CREATE TABLE resource_reservation(enterprise_id uuid NOT NULL,id uuid NOT NULL,plan_id uuid NOT NULL,plan_version integer NOT NULL,resource_key text NOT NULL,amount bigint NOT NULL CHECK(amount>0),state text NOT NULL CHECK(state IN ('reserved','released','settled')),PRIMARY KEY(enterprise_id,id),UNIQUE(enterprise_id,plan_id,plan_version,resource_key),FOREIGN KEY(enterprise_id,resource_key) REFERENCES resource_budget(enterprise_id,resource_key),FOREIGN KEY(enterprise_id,plan_id,plan_version) REFERENCES runtime_plan(enterprise_id,id,version));
CREATE TABLE runtime_event(enterprise_id uuid NOT NULL,run_id uuid NOT NULL,sequence bigint NOT NULL,kind text NOT NULL,details jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(enterprise_id,run_id,sequence),FOREIGN KEY(enterprise_id,run_id) REFERENCES agent_run(enterprise_id,id));
CREATE TABLE event_outbox(enterprise_id uuid NOT NULL,id uuid NOT NULL,run_id uuid NOT NULL,sequence bigint NOT NULL,kind text NOT NULL,delivery_state text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,PRIMARY KEY(enterprise_id,id),UNIQUE(enterprise_id,run_id,sequence),FOREIGN KEY(enterprise_id,run_id,sequence) REFERENCES runtime_event(enterprise_id,run_id,sequence));
CREATE TABLE event_inbox(enterprise_id uuid NOT NULL,source_id text NOT NULL,event_id text NOT NULL,payload_hash text NOT NULL,source_version integer NOT NULL,action_id uuid NOT NULL,payload jsonb NOT NULL,processed_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(enterprise_id,source_id,event_id),FOREIGN KEY(enterprise_id,action_id) REFERENCES runtime_action(enterprise_id,id));
CREATE TABLE event_conflict(enterprise_id uuid NOT NULL,id uuid NOT NULL,source_id text NOT NULL,event_id text NOT NULL,old_hash text NOT NULL,new_hash text NOT NULL,PRIMARY KEY(enterprise_id,id));
CREATE TABLE runtime_request(enterprise_id uuid NOT NULL,operation text NOT NULL,idempotency_key text NOT NULL,args_hash text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(enterprise_id,operation,idempotency_key));
-- Only application-role RLS writes; immutable evidence/events cannot be overwritten.
-- 应用角色使用RLS写入，已记录证据/事件不可覆盖。
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['agent_definition','agent_run','runtime_task','runtime_plan','runtime_approval','runtime_action','runtime_receipt','fulfillment_obligation','resource_budget','resource_reservation','runtime_event','event_outbox','event_inbox','event_conflict','runtime_request'] LOOP
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY enterprise_isolation ON %I USING(enterprise_id::text=current_setting(''app.enterprise_id'',true)) WITH CHECK(enterprise_id::text=current_setting(''app.enterprise_id'',true))',t);
  EXECUTE format('GRANT SELECT,INSERT,UPDATE ON %I TO eb_app',t);
 END LOOP;
END $$;
REVOKE UPDATE ON agent_definition,runtime_approval,runtime_receipt,runtime_event,event_inbox,event_conflict,runtime_request FROM eb_app;
GRANT INSERT ON audit_event TO eb_app;
